const API = "https://api.codegrove.test";

const status = document.querySelector("#status");
const list = document.querySelector("#planets");
const lookup = document.querySelector("#lookup");

// 1. Load the planets, show the ringed ones and the count
async function loadPlanets() {
  try {
    const response = await fetch(`${API}/planets`);
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    const planets = await response.json();
    const ringed = planets.filter((planet) => planet.hasRings);

    for (const planet of ringed) {
      const li = document.createElement("li");
      li.textContent = `${planet.name} (${planet.moons} moons)`;
      list.append(li);
    }
    status.textContent = `${ringed.length} ringed planets`;
  } catch (error) {
    status.textContent = "Couldn't load planets";
    console.error(error);
  }
}

// 2. Look up one planet by id
async function findPlanet(id) {
  const response = await fetch(`${API}/planets/${id}`);
  if (response.ok) {
    const planet = await response.json();
    lookup.textContent = planet.name;
  } else {
    lookup.textContent = `Planet not found (${response.status})`;
  }
}

loadPlanets();
findPlanet(99);

